// Package e2ee implements the Waft v2 end-to-end encryption format.
//
// Key derivation: PBKDF2-HMAC-SHA256(passphrase, per-account salt, 600000 iterations) -> 32-byte AES-256 key.
// The salt is generated by the server when the account is created and is returned by GET /v2/me.
// Two accounts with the same passphrase therefore never share a key.
//
// Payload format (events): base64( 12-byte random nonce || AES-256-GCM ciphertext || 16-byte tag ).
//
// File format (GPF1): the file body itself is encrypted in fixed 64 KiB segments so it can be
// streamed and resumed. See stream.go.
//
// The browser client (static/app.js) implements the identical format with WebCrypto.
package e2ee

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/base64"
	"encoding/json"
	"errors"
	"fmt"
	"io"

	"golang.org/x/crypto/pbkdf2"
)

const (
	// KDFIterations follows the OWASP recommendation for PBKDF2-HMAC-SHA256.
	KDFIterations = 600000
	keyLen        = 32
	minSaltLen    = 16

	// KeyCheckMarker is sealed by the first client and stored on the server so that other
	// devices can detect a mismatched passphrase before they produce unreadable frames.
	KeyCheckMarker = "gopush-key-check-v2"
)

// ErrAuthFailed is returned when a ciphertext does not authenticate under the key.
var ErrAuthFailed = errors.New("e2ee: authentication failed (wrong passphrase or tampered data)")

// SecretPayload holds the sensitive fields carried inside Envelope.Ciphertext.
type SecretPayload struct {
	Title      string `json:"title,omitempty"`
	Body       string `json:"body,omitempty"`
	URL        string `json:"url,omitempty"`
	AppName    string `json:"app_name,omitempty"`
	FileName   string `json:"file_name,omitempty"`
	FileSHA256 string `json:"file_sha256,omitempty"` // SHA-256 of the plaintext file
	FileSize   int64  `json:"file_size,omitempty"`   // plaintext size in bytes
	MimeType   string `json:"mime_type,omitempty"`
}

// Key is a derived account key. It is safe for concurrent use.
type Key struct {
	aead cipher.AEAD
}

// DecodeSalt decodes the base64 salt returned by the server.
func DecodeSalt(b64 string) ([]byte, error) {
	salt, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		return nil, fmt.Errorf("e2ee: invalid salt encoding: %w", err)
	}
	if len(salt) < minSaltLen {
		return nil, fmt.Errorf("e2ee: salt too short (%d bytes)", len(salt))
	}
	return salt, nil
}

// DeriveKey derives the account key. This is deliberately slow; derive once and reuse the Key.
func DeriveKey(passphrase string, salt []byte) (*Key, error) {
	if passphrase == "" {
		return nil, errors.New("e2ee: empty passphrase")
	}
	if len(salt) < minSaltLen {
		return nil, fmt.Errorf("e2ee: salt too short (%d bytes)", len(salt))
	}
	raw := pbkdf2.Key([]byte(passphrase), salt, KDFIterations, keyLen, sha256.New)
	block, err := aes.NewCipher(raw)
	if err != nil {
		return nil, err
	}
	aead, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	return &Key{aead: aead}, nil
}

// SealBytes encrypts arbitrary bytes into the base64 event format.
func (k *Key) SealBytes(plain []byte) (string, error) {
	nonce := make([]byte, k.aead.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return "", err
	}
	return base64.StdEncoding.EncodeToString(k.aead.Seal(nonce, nonce, plain, nil)), nil
}

// OpenBytes decrypts the base64 event format.
func (k *Key) OpenBytes(b64 string) ([]byte, error) {
	raw, err := base64.StdEncoding.DecodeString(b64)
	if err != nil {
		return nil, fmt.Errorf("e2ee: invalid base64: %w", err)
	}
	ns := k.aead.NonceSize()
	if len(raw) < ns+k.aead.Overhead() {
		return nil, errors.New("e2ee: ciphertext too short")
	}
	plain, err := k.aead.Open(nil, raw[:ns], raw[ns:], nil)
	if err != nil {
		return nil, ErrAuthFailed
	}
	return plain, nil
}

// Seal encrypts a SecretPayload.
func (k *Key) Seal(p SecretPayload) (string, error) {
	plain, err := json.Marshal(p)
	if err != nil {
		return "", err
	}
	return k.SealBytes(plain)
}

// Open decrypts a SecretPayload.
func (k *Key) Open(b64 string) (SecretPayload, error) {
	var out SecretPayload
	plain, err := k.OpenBytes(b64)
	if err != nil {
		return out, err
	}
	if err := json.Unmarshal(plain, &out); err != nil {
		return out, fmt.Errorf("e2ee: malformed payload: %w", err)
	}
	return out, nil
}

// NewKeyCheck returns a value the server stores so other devices can verify the passphrase.
func (k *Key) NewKeyCheck() (string, error) {
	return k.SealBytes([]byte(KeyCheckMarker))
}

// VerifyKeyCheck reports whether the key matches the stored key-check value.
func (k *Key) VerifyKeyCheck(check string) bool {
	plain, err := k.OpenBytes(check)
	return err == nil && string(plain) == KeyCheckMarker
}
